28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    @Email
55	    private String email;
56	
57	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
58	    private Set<Pet> pets;
59	
60	    public String getAddress() {
61	        return this.address;
62	    }
63	
64	    public void setAddress(String address) {
65	        this.address = address;
66	    }
67	
68	    public String getCity() {
69	        return this.city;
70	    }
71	
72	    public void setCity(String city) {
73	        this.city = city;
74	    }
75	
76	    public String getTelephone() {
77	        return this.telephone;
78	    }
79	
80	    public void setTelephone(String telephone) {
81	        this.telephone = telephone;
82	    }
83	
84	    public String getEmail() {
85	        return this.email;
86	    }
87	
88	    public void setEmail(String email) {
89	        this.email = email;
90	    }
91	
92	    protected Set<Pet> getPetsInternal() {
93	        if (this.pets == null) {
94	            this.pets = new HashSet<>();
95	        }
96	        return this.pets;
97	    }
98	
99	    protected void setPetsInternal(Set<Pet> pets) {
100	        this.pets = pets;
101	    }
102	
103	    public List<Pet> getPets() {
104	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
105	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
106	        return Collections.unmodifiableList(sortedPets);
107	    }
108	
109	    public void setPets(List<Pet> pets) {
110	        this.pets = new HashSet<>(pets);
111	    }
112	
113	    public void addPet(Pet pet) {
114	        getPetsInternal().add(pet);
115	        pet.setOwner(this);
116	    }
117	
118	    /**
119	     * Return the Pet with the given name, or null if none found for this Owner.
120	     *
121	     * @param name to test
122	     * @return true if pet name is already in use
123	     */
124	    public Pet getPet(String name) {
125	        return getPet(name, false);
126	    }
127	
128	    /**
129	     * Return the Pet with the given name, or null if none found for this Owner.
130	     *
131	     * @param name to test
132	     * @return true if pet name is already in use
133	     */
134	    public Pet getPet(String name, boolean ignoreNew) {
135	        name = name.toLowerCase();
136	        for (Pet pet : getPetsInternal()) {
137	            if (!ignoreNew || !pet.isNew()) {
138	                String compName = pet.getName();
139	                compName = compName.toLowerCase();
140	                if (compName.equals(name)) {
141	                    return pet;
142	                }
143	            }
144	        }
145	        return null;
146	    }
147	
148	    public Pet getPet(Integer petId) {
149	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
150	    }
151	
152	    @Override
153	    public String toString() {
154	        return new ToStringCreator(this)
155	
156	            .append("id", this.getId())
157	            .append("new", this.isNew())
158	            .append("lastName", this.getLastName())
159	            .append("firstName", this.getFirstName())
160	            .append("address", this.address)
161	            .append("city", this.city)
162	            .append("telephone", this.telephone)
163	            .toString();
164	    }
165	}
